param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$ok,[string]$message){if(-not$ok){throw "Assertion failed: $message"}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Xld([double[]]$rows,[double[]]$columns){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]$rows,[HalconDotNet.HTuple]$columns);$x}
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s43-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadata=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true);$layoutType=$assembly.GetType('HalconWinFormsDemo.Models.VmProductionRunLayoutData',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public';$arg=New-Object 'object[]' 1;$arg[0]=$temp.ToString();$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke($arg);$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke($arg);$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$field=$main.GetField($name,$all);if($null-eq$field){throw "Missing field $name"};$field.GetValue($window)}
$flow=$main.GetField('flowTools',$private).GetValue($window);$create=$main.GetMethod('CreateFlowTool',$private);$run=$main.GetMethod('RunXldContourCropTool',$private);$execute=$main.GetMethod('ExecuteFlowTool',$private);$capture=$main.GetMethod('CaptureRecipe',$private);$applyRecipe=$main.GetMethod('ApplyRecipe',$private);$dispose=$main.GetMethod('DisposeFlowTools',$private)
function Tool([string]$kind,[string]$name){$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function RunCrop($tool,$xld){try{$run.Invoke($window,[object[]]@($tool,$xld))}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};$value}

foreach($name in @('OpenProductionLayoutDesignerButton','ProductionLayoutDesignerPanel','ProductionLayoutWidgetListBox','ProductionWidgetStack','ProductionSchemeWidget','ProductionOverallResultWidget','ProductionStatisticsWidget','ProductionRunControlWidget','ProductionBatchWidget','ProductionAlarmWidget','ProductionRecentResultsWidget','ProductionImageTitleText','DockXldContourCropPanel','DockXldCropRow1TextBox','DockXldCropColumn1TextBox','DockXldCropRow2TextBox','DockXldCropColumn2TextBox','DockXldCropCloseContoursCheckBox')){Assert($null-ne(F $name)) "$name missing"}
$cropKind=[Enum]::Parse($kindType,'XldContourCrop');$inputs=$metadata.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($cropKind));$outputs=$metadata.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($cropKind));Assert(($inputs|Where-Object{$_.PortName-eq'XLD'-and$_.DataType-eq'XLD'-and-not$_.IsOptional}).Count-eq1) 'Typed required XLD input missing';foreach($port in @('XLD','InputContourCount','ContourCount','InputTotalLength','TotalLength','MinRow','MinColumn','MaxRow','MaxColumn','CropRectangle','CloseContours','Parameters','ResultCode')){Assert(($outputs|Where-Object PortName -eq $port).Count-eq1) "Output $port missing"}

$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.Width=1740;$window.Height=940;$window.Show();Pump 250
# A: same page live preview, required visibility, title/order/visibility, apply/cancel/default, recipe and undo.
$main.GetMethod('OpenProductionLayoutDesignerButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;Pump 100;Assert([bool](F 'productionLayoutDesignMode')) 'Designer did not enter live preview';Assert((F 'ProductionRunPanel').Visibility.ToString()-eq'Visible' -and (F 'ProductionLayoutDesignerPanel').Visibility.ToString()-eq'Visible') 'Designer is not using production page preview'
$draft=F 'productionLayoutDraftItems';Assert($draft.Count-eq8) 'Eight real production widgets were not loaded';$overall=$draft|Where-Object WidgetId -eq 'OverallResult';$image=$draft|Where-Object WidgetId -eq 'Image';$runControl=$draft|Where-Object WidgetId -eq 'RunControl';Assert($overall.IsRequired-and$image.IsRequired-and$runControl.IsRequired-and-not$overall.CanHide) 'Required widget protection missing';$overall.IsVisible=$false;Assert($overall.IsVisible) 'Required result widget was hidden'
$statistics=$draft|Where-Object WidgetId -eq 'Statistics';$statistics.Title='S43 Shift Statistics';$statistics.IsVisible=$false;(F 'ProductionLayoutWidgetListBox').SelectedItem=$statistics;$main.GetMethod('ProductionLayoutDraftValue_Changed',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;Assert((F 'ProductionStatisticsWidget').Header-eq'S43 Shift Statistics'-and(F 'ProductionStatisticsWidget').Visibility.ToString()-eq'Collapsed') 'Draft title/visibility did not live-preview'
$main.GetMethod('ApplyProductionLayoutButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$recipe=$capture.Invoke($window,@());$saved=$recipe.ProductionRunLayout.Widgets|Where-Object WidgetId -eq 'Statistics';Assert($saved.Title-eq'S43 Shift Statistics'-and-not$saved.IsVisible) 'Layout was not captured in recipe';Assert((F 'flowUndoHistory').Count-gt0) 'Layout apply did not enter undo history'
$statistics.Title='Discarded';$main.GetMethod('ProductionLayoutDraftValue_Changed',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$main.GetMethod('CancelProductionLayoutButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;Assert((F 'ProductionStatisticsWidget').Header-eq'S43 Shift Statistics') 'Cancel did not restore applied layout'
$legacy=$assembly.GetType('HalconWinFormsDemo.Models.VisionRecipe',$true).GetConstructor([Type[]]@()).Invoke(@());$legacy.ProductionRunLayout=$null;$applyRecipe.Invoke($window,[object[]]@($legacy))|Out-Null;$normalized=F 'productionRunLayout';Assert($normalized.Widgets.Count-eq8-and($normalized.Widgets|Where-Object WidgetId -eq 'OverallResult').IsVisible) 'Old recipe did not get safe S42 default layout'

# B: all crossing directions, inside/outside/tangent, open/closed/multiple/empty, close semantics, lifecycle and downstream.
$tool=Tool XldContourCrop 'S43 Crop';$tool.Parameters.XldCropRow1=10;$tool.Parameters.XldCropColumn1=10;$tool.Parameters.XldCropRow2=40;$tool.Parameters.XldCropColumn2=40
foreach($case in @(@([double[]]@(25,25),[double[]]@(0,60)),@([double[]]@(0,60),[double[]]@(25,25)),@([double[]]@(0,60),[double[]]@(0,60)),@([double[]]@(60,0),[double[]]@(0,60)))){$x=Xld $case[0] $case[1];try{$record=RunCrop $tool $x;Assert($record.ResultCode-eq'OK'-and[int](Out $tool ContourCount)-ge1) 'Crossing contour was not cropped'}finally{$x.Dispose()}}
$inside=Xld ([double[]]@(15,20,30)) ([double[]]@(15,25,30));try{RunCrop $tool $inside|Out-Null;Assert([Math]::Abs([double](Out $tool TotalLength)-[double](Out $tool InputTotalLength))-lt.001) 'Fully inside contour changed'}finally{$inside.Dispose()}
$outside=Xld ([double[]]@(50,55)) ([double[]]@(50,55));try{$record=RunCrop $tool $outside;Assert($record.ResultCode-eq'NG'-and[int](Out $tool ContourCount)-eq0) 'Outside contour was retained'}finally{$outside.Dispose()}
$tangent=Xld ([double[]]@(10,10,10)) ([double[]]@(0,25,60));try{RunCrop $tool $tangent|Out-Null;Assert([int](Out $tool ContourCount)-ge1) 'Boundary tangent contour disappeared'}finally{$tangent.Dispose()}
$closed=Xld ([double[]]@(0,0,50,50,0)) ([double[]]@(0,50,50,0,0));try{$tool.Parameters.XldCropCloseContours=$true;RunCrop $tool $closed|Out-Null;$trueLength=[double](Out $tool TotalLength);$tool.Parameters.XldCropCloseContours=$false;$old=Out $tool XLD;RunCrop $tool $closed|Out-Null;Assert($old.IsDisposed) 'Prior managed crop XLD was not disposed';Assert([double](Out $tool TotalLength)-lt$trueLength) 'CloseContours did not alter originally closed contour closure'}finally{$closed.Dispose()}
[HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);try{$record=RunCrop $tool $empty;Assert($record.ResultCode-eq'NG'-and[int](Out $tool InputContourCount)-eq0) 'Empty input semantics wrong'}finally{$empty.Dispose()}
$invalid=Tool XldContourCrop 'Invalid';$invalid.Parameters.XldCropRow1=20;$invalid.Parameters.XldCropRow2=20;$input=Xld ([double[]]@(0,50)) ([double[]]@(25,25));try{$rejected=$false;try{RunCrop $invalid $input|Out-Null}catch{$rejected=$true};Assert $rejected 'Invalid rectangle was accepted'}finally{$input.Dispose();$invalid.Dispose()}
$dispose.Invoke($window,@())|Out-Null;$flow.Clear();$producer=Tool SubpixelEdgeExtraction 'Producer';$crop=Tool XldContourCrop 'Crop Flow';$fit=Tool XldLineFitting 'Fit';$judge=Tool NumericJudge 'Judge';$crop.Parameters.XldCropRow1=10;$crop.Parameters.XldCropColumn1=10;$crop.Parameters.XldCropRow2=40;$crop.Parameters.XldCropColumn2=40;$crop.SetInputBinding('XLD',$producer.ToolId,'XLD');$fit.SetInputBinding('XLD',$crop.ToolId,'XLD');$judge.SetInputBinding('Value',$crop.ToolId,'ContourCount');$judge.InputToolId=$crop.ToolId;$judge.InputPortName='ContourCount';$judge.NumericLowerLimit=1;$judge.NumericUpperLimit=10;foreach($item in @($producer,$crop,$fit,$judge)){$flow.Add($item)};$flowXld=Xld ([double[]]@(25,25)) ([double[]]@(0,60));try{$producer.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($flowXld,$producer.ToolId,$producer.InstanceName,'XLD')));$producer.ResultCode='OK'}finally{$flowXld.Dispose()};foreach($item in @($crop,$fit,$judge)){$execute.Invoke($window,[object[]]@($item,'S43 chain'))|Out-Null};Assert($crop.ResultCode-eq'OK'-and$fit.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'Crop outputs did not drive XLD and Number downstream';$upstream=Out $producer XLD;$upstream.Dispose();$failed=$false;try{$execute.Invoke($window,[object[]]@($crop,'disposed'))|Out-Null}catch{$failed=$true};Assert $failed 'Disposed upstream was accepted'
(F 'FlowToolList').SelectedItem=$crop;$main.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($crop))|Out-Null;Assert((F 'DockXldContourCropPanel').Visibility.ToString()-eq'Visible') 'Crop dock panel not synchronized';$recipe=$capture.Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object ToolType -eq 'XldContourCrop'|Select-Object -First 1;Assert($saved.Parameters.XldCropRow1-eq10-and$saved.Parameters.XldCropCloseContours) 'Crop parameters not persisted'
$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output 'S43 production layout designer and HALCON XLD rectangle crop smoke tests passed.'
